#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;
    if (a > b) {
        swap(a, b);
    }
    if (a == 1) {
        cout << 6 * (b / 6) + 2 * max(0, (b % 6) - 3) << "\n";
    } else if (a == 2) {
        if (b == 2) {
            cout << 0 << "\n";
        } else if (b == 1 || b == 3 || b == 7) {
            cout << a * b - 2 << "\n";
        } else {
            cout << a * b << "\n";
        }
    } else {
        cout << ((a * b) / 2) * 2 << "\n";
    }
    return 0;
}
